<?php
/**
 * PlotBird Analytics - configuration container.
 *
 * The real configuration lives in /config/config.php and is generated by the
 * installer. During installation no such file exists yet, so the installer
 * pushes its values in at runtime with Config::merge().
 *
 * @package PlotBird
 */

declare(strict_types=1);

namespace PlotBird;

final class Config
{
    /** @var array<string,mixed> Fully qualified configuration values. */
    private static array $data = [];

    /** @var bool Whether a configuration has been loaded or merged. */
    private static bool $loaded = false;

    /**
     * Absolute path of the (possibly not yet existing) configuration file.
     */
    public static function path(): string
    {
        return PB_ROOT . '/config/config.php';
    }

    /**
     * Whether the installation has been completed (config file present).
     */
    public static function isInstalled(): bool
    {
        return is_file(self::path());
    }

    /**
     * Load /config/config.php. Loading twice is a no-op.
     *
     * A missing file is not an error: the installer runs precisely when there
     * is no configuration yet, and every consumer is expected to check
     * Config::isInstalled() first. A file that exists but does not return an
     * array is always an error - that is a broken deployment, not a fresh one.
     *
     * @throws \RuntimeException when the file exists but is not a config array.
     */
    public static function load(?string $path = null): void
    {
        if (self::$loaded) {
            return;
        }
        $path = $path ?? self::path();

        if (!is_file($path)) {
            self::$data   = [];
            self::$loaded = true;
            return;
        }

        /** @var mixed $data */
        $data = require $path;
        if (!is_array($data)) {
            throw new \RuntimeException('Configuration file must return an array: ' . $path);
        }
        self::$data   = $data;
        self::$loaded = true;
    }

    /**
     * Throw unless a usable configuration was loaded.
     *
     * @throws \RuntimeException
     */
    public static function assertInstalled(): void
    {
        if (!self::isInstalled()) {
            throw new \RuntimeException('PlotBird Analytics is not installed yet.');
        }
        self::load();
    }

    /**
     * Merge values over the current configuration (used by the installer and
     * by tests). Merging marks the configuration as loaded.
     *
     * @param array<string,mixed> $data
     */
    public static function merge(array $data): void
    {
        self::$data   = array_replace_recursive(self::$data, $data);
        self::$loaded = true;
    }

    /**
     * Read a dotted configuration key: Config::get('db.host').
     *
     * @param mixed $default
     * @return mixed
     */
    public static function get(string $key, $default = null)
    {
        if (!self::$loaded) {
            self::load();
        }
        $value = self::$data;
        foreach (explode('.', $key) as $segment) {
            if (!is_array($value) || !array_key_exists($segment, $value)) {
                return $default;
            }
            $value = $value[$segment];
        }
        return $value;
    }

    /**
     * Write a dotted configuration key at runtime (never persisted here).
     *
     * @param mixed $value
     */
    public static function set(string $key, $value): void
    {
        $ref = &self::$data;
        foreach (explode('.', $key) as $segment) {
            if (!isset($ref[$segment]) || !is_array($ref[$segment])) {
                $ref[$segment] = [];
            }
            $ref = &$ref[$segment];
        }
        $ref = $value;
        self::$loaded = true;
    }

    /**
     * @return array<string,mixed>
     */
    public static function all(): array
    {
        if (!self::$loaded) {
            self::load();
        }
        return self::$data;
    }

    /**
     * Renders a config.php file body for the given values.
     *
     * Kept here (not in the installer) so that the generated file and the
     * sample file can never drift apart silently.
     *
     * @param array<string,mixed> $values
     */
    public static function export(array $values): string
    {
        $dump = self::exportValue($values, 0);

        return "<?php\n"
            . "/**\n"
            . " * PlotBird Analytics - generated configuration.\n"
            . " *\n"
            . " * Created by the installer on " . gmdate('Y-m-d H:i:s') . " UTC.\n"
            . " * Contains credentials: keep it out of version control and make sure\n"
            . " * the web server does not serve it (see /config/.htaccess).\n"
            . " *\n"
            . " * Deleting this file makes the installer run again.\n"
            . " */\n\n"
            . "return " . $dump . ";\n";
    }

    /**
     * Recursively renders a value as short-array PHP source.
     *
     * @param mixed $value
     */
    private static function exportValue($value, int $depth): string
    {
        $indent = str_repeat('    ', $depth + 1);
        $close  = str_repeat('    ', $depth);

        if (is_array($value)) {
            if ($value === []) {
                return '[]';
            }
            $isList = array_keys($value) === range(0, count($value) - 1);
            $lines  = [];
            foreach ($value as $key => $item) {
                $prefix = $isList ? '' : var_export($key, true) . ' => ';
                $lines[] = $indent . $prefix . self::exportValue($item, $depth + 1) . ',';
            }
            return "[\n" . implode("\n", $lines) . "\n" . $close . ']';
        }

        if (is_string($value)) {
            return var_export($value, true);
        }
        if (is_bool($value)) {
            return $value ? 'true' : 'false';
        }
        if ($value === null) {
            return 'null';
        }
        if (is_int($value) || is_float($value)) {
            return var_export($value, true);
        }

        // Anything else (object, resource) is not a valid config value.
        return 'null';
    }
}
